"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["43473"],{49018(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.tipo_conceito.valor_categorico_rotulo_invalido","status":422,"titulo":"R\xf3tulo do valor categ\xf3rico inv\xe1lido"},"descricao":{"codigo":"uniplus.configuracao.tipo_conceito.valor_categorico_rotulo_invalido","requisitos":[],"oQueAconteceu":["Um item de `valores`, na cria\xe7\xe3o (`POST /api/configuracao/admin/tipos-conceito`) ou na atualiza\xe7\xe3o (`PUT /api/configuracao/admin/tipos-conceito/{id}`) de um tipo categ\xf3rico, traz um `rotulo` que n\xe3o \xe9 aceito: ausente, vazio ou s\xf3 com espa\xe7os; com mais de 100 caracteres, depois de aparado e normalizado; ou com o caractere nulo ou texto que n\xe3o \xe9 Unicode v\xe1lido. O r\xf3tulo \xe9 o texto que as pessoas leem ao escolher o valor. Um item `null` na lista chega ao dom\xednio e tamb\xe9m cai aqui, junto com [c\xf3digo de valor categ\xf3rico inv\xe1lido](/erros/uniplus.configuracao.tipo_conceito.valor_categorico_codigo_invalido).","A recusa vem na lista `errors` da resposta, com `field` igual a `valores[i].rotulo`, em que `i` \xe9 a posi\xe7\xe3o do item, contada a partir de 0. Cada item com problema gera a pr\xf3pria entrada, e nada \xe9 gravado. A recusa s\xf3 aparece em tipo de natureza `categorico`.","Todo item de `valores` precisa dizer se conta como aprova\xe7\xe3o: o item que omite `contaComoAprovacao` \xe9 recusado no pr\xf3prio campo, com [conta como aprova\xe7\xe3o obrigat\xf3ria](/erros/uniplus.configuracao.tipo_conceito.valor_categorico_conta_como_aprovacao_obrigatoria), junto das recusas de c\xf3digo e de r\xf3tulo do mesmo item. Por isso `valores: [{}]` produz as tr\xeas recusas, uma para cada campo.","Na atualiza\xe7\xe3o, com o corpo desserializ\xe1vel e o `id` do corpo igual ao da rota, a confer\xeancia do corpo vem antes da busca do tipo: com um `{id}` que n\xe3o existe, a resposta \xe9 esta, e n\xe3o a de [tipo de conceito n\xe3o encontrado](/erros/uniplus.configuracao.tipo_conceito.nao_encontrado). O corpo que n\xe3o desserializa e o `id` do corpo diferente do da rota s\xe3o recusados antes, com 400 e sem o c\xf3digo desta p\xe1gina."],"comoResolver":["Corrija o r\xf3tulo do item indicado em `field`, com at\xe9 100 caracteres, mantendo no item o `contaComoAprovacao` (por exemplo `{ \\"codigo\\": \\"APTO\\", \\"rotulo\\": \\"Apto\\", \\"contaComoAprovacao\\": true }`), e repita o pedido."],"ondeAparece":["Cria\xe7\xe3o de um tipo de conceito","Atualiza\xe7\xe3o de um tipo de conceito"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Tipo conceito"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);